-- Coordination references only. No source narratives, identities or evidence copies.
INSERT INTO roles(name) VALUES('TRUST_SOCIAL'),('TRUST_LISTENER'),('TRUST_CLINIC'),('TRUST_FINANCE'),('TRUST_ACCOUNT'),('TRUST_EDUCATION'),('TRUST_PLATFORM') ON CONFLICT(name) DO NOTHING;
CREATE TABLE trust_cases(
 id UUID PRIMARY KEY DEFAULT uuidv7(), source_kind TEXT NOT NULL CHECK(source_kind IN('REPORT','CLINIC_INCIDENT','REPUTATION_CASE','SUPPORT_REQUEST')),
 source_id UUID NOT NULL, domain TEXT NOT NULL CHECK(domain IN('SOCIAL','GROUP','LISTENER','CLINIC','FINANCE','ACCOUNT','EDUCATION','PLATFORM')),
 category TEXT NOT NULL CHECK(category IN('POST','COMMENT','HARASSMENT','THREAT','PRIVACY','GROUP_MISCONDUCT','LISTENER_MISCONDUCT','PROFESSIONAL_CONDUCT','FINANCIAL_SERVICE','ACCOUNT_ACCESS','EDUCATIONAL_CONTENT','PLATFORM_SAFETY')),
 severity TEXT NOT NULL CHECK(severity IN('CRITICAL','HIGH','MEDIUM','LOW')),
 state TEXT NOT NULL DEFAULT 'RECEIVED' CHECK(state IN('RECEIVED','TRIAGED','WAITING_FOR_OPERATOR','UNDER_REVIEW','ACTION_PENDING_APPROVAL','ACTIONED','APPEALED','APPEAL_REVIEW','RESOLVED','CLOSED')),
 revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0), assignee_id UUID REFERENCES users(id), created_by UUID REFERENCES users(id),
 purpose TEXT NOT NULL CHECK(purpose='SAFETY_COORDINATION'), result TEXT CHECK(result IN('SOURCE_REVIEW_REQUIRED','SOURCE_OUTCOME_CONFIRMED','NO_ACTION_REQUIRED')),
 action_author UUID REFERENCES users(id), action_session UUID REFERENCES user_sessions(id), approval_expires_at TIMESTAMPTZ, independent_reviewer UUID REFERENCES users(id), source_snapshot TEXT,
 created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(source_kind,source_id)
);
CREATE INDEX trust_case_queue ON trust_cases(domain,state,created_at,id);
CREATE TABLE trust_case_events(
 id UUID PRIMARY KEY DEFAULT uuidv7(), case_id UUID NOT NULL REFERENCES trust_cases(id) ON DELETE CASCADE,
 revision BIGINT NOT NULL,actor_id UUID REFERENCES users(id),from_state TEXT,to_state TEXT NOT NULL,
 reason_code TEXT NOT NULL CHECK(reason_code IN('SOURCE_RECEIVED','TRIAGE','ASSIGNMENT','COVERAGE_UNAVAILABLE','REVIEW_STARTED','DUAL_REVIEW_REQUESTED','INDEPENDENT_APPROVAL','SOURCE_ACTION_CONFIRMED','NO_ACTION','SOURCE_APPEALED','INDEPENDENT_APPEAL_REVIEW','SOURCE_RESOLVED','CLOSED','APPROVAL_REVOKED')),
 created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(case_id,revision)
);
CREATE TABLE trust_coverage(
 id UUID PRIMARY KEY DEFAULT uuidv7(), domain TEXT NOT NULL CHECK(domain IN('SOCIAL','GROUP','LISTENER','CLINIC','FINANCE','ACCOUNT','EDUCATION','PLATFORM')),
 operator_id UUID NOT NULL REFERENCES users(id),approved_by UUID NOT NULL REFERENCES users(id),starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,
 capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 50),acknowledged_at TIMESTAMPTZ,heartbeat_at TIMESTAMPTZ,session_id UUID REFERENCES user_sessions(id),token_version INTEGER,revoked_at TIMESTAMPTZ,
 CHECK(operator_id<>approved_by),CHECK(ends_at>starts_at AND ends_at<=starts_at+INTERVAL '12 hours')
);
CREATE INDEX trust_coverage_current ON trust_coverage(domain,ends_at) WHERE revoked_at IS NULL;
